-- The signed-in Clerk user id (the `sub` claim of the Clerk session token).
-- Supabase's third-party auth verifies the token; auth.jwt() exposes its claims.
CREATE OR REPLACE FUNCTION public.uid() RETURNS text
LANGUAGE sql STABLE AS $$ SELECT nullif(auth.jwt() ->> 'sub', '') $$;

-- A fresh class join code: 6 characters, no look-alikes (no 0/O, 1/I).
CREATE OR REPLACE FUNCTION public.new_join_code() RETURNS text
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  code text;
BEGIN
  LOOP
    code := '';
    FOR i IN 1..6 LOOP
      code := code || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
    END LOOP;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.classes c WHERE c.join_code = code);
  END LOOP;
  RETURN code;
END $$;

